/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy.ndimage import label,find_objects
A=np.load('source_pixels.npz')['rgb']
for a,b in [(95,0),(95,11),(95,22),(95,30),(95,31),(95,44),(44,30),(31,30),(32,31)]:
 d=np.max(abs(A[a].astype(int)-A[b].astype(int)),2)
 for th in [8,20,40]:
  m=d>th; lab,n=label(m); cs=[]
  for k,s in enumerate(find_objects(lab),1):
   if s:
    ar=np.sum(lab[s]==k)
    if ar>=3: cs.append((int(ar),(s[1].start,s[0].start,s[1].stop-1,s[0].stop-1),round(float(d[lab==k].mean()))))
  print(a+1,b+1,'th',th,sorted(cs,reverse=True)[:20])
